// services/api.js
import axios from 'axios';

// Cấu hình base URL từ biến môi trường hoặc mặc định
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3000/api';

// Tạo instance axios với cấu hình cơ bản
const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Interceptor để tự động thêm token vào header
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Interceptor để xử lý response chung
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      // Xử lý khi token hết hạn hoặc không hợp lệ
      localStorage.removeItem('token');
      window.location.href = '/login'; // Redirect về trang login
    }
    return Promise.reject(error);
  }
);

// API Auth
export const authAPI = {
  register: (userData) => api.post('/auth/signup', userData),
  login: (credentials) => api.post('/auth/login', credentials),
  // Có thể thêm các phương thức auth khác như logout, refresh token...
};

// API Products
export const productAPI = {
  getProducts: () => api.get('/products'),
  getProductDetails: (id) => api.get(`/products/${id}`),
  // Thêm các phương thức khác như create, update, delete...
};

// API Orders
export const orderAPI = {
  createOrder: (orderData) => api.post('/orders', orderData),
  getOrders: (userId) => api.get(`/orders/${userId}`),
  // Thêm các phương thức khác liên quan đến đơn hàng
};

export default api;
